const JOURNEYS = [{"id":"PU-06","epic":"E1","name":"Show actions for the current punch state","actor":"Hourly employee","story":"As an hourly employee, I want to see the punch action available for my current state so that I can continue the punch flow.","trigger":"Employee taps a punch action","pre":"Current punch state known","flow":"1. Open Punch. 2. See actions for the current state: Out, In, or On break. 3. Choose an available action.","alt":"UKG returns an error for a submitted punch -> show the error message returned by UKG.","rules":"Out -> Punch In; In -> Transfer, Start Break, Punch Out; On break -> End Break, Punch Out. CloudApper sends a selected punch to UKG and displays any returned error, including duplicate-punch errors.","api":"None for displaying the available actions; punch submissions are sent to UKG.","ev":"Confirmed - Spiro documents","src":"SRC-06, FSD TK-1","pri":"Must","cov":"Covered","demo":["ava","punch","punch-in","Ava Mitchell > Punch (buttons follow state)"],"q":"","ac":[["I am punched in","I look at Punch","I see Transfer, Start Break, and Punch Out; Punch In is unavailable"]],"specStatus":"Confirmed","specRef":"§5.1.1","shots":[{"src":"journeys/prototype/desktop/PU-06-step1.png","alt":"Desktop view: Punched out: Punch In is available, and Start Break and Punch Out are not.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-06-step1.png","alt":"Mobile view: Punched out: Punch In is available, and Start Break and Punch Out are not.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-06-step2.png","alt":"Desktop view: Punched in: the actions are Add Transfer, Start Break, and Punch Out.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-06-step2.png","alt":"Mobile view: Punched in: the actions are Add Transfer, Start Break, and Punch Out.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/PU-06-step3.png","alt":"Desktop view: On break: End Break is the primary action and Punch Out is secondary.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/PU-06-step3.png","alt":"Mobile view: On break: End Break is the primary action and Punch Out is secondary.","caption":"Step 3 · Mobile"}]},{"id":"CC-04","epic":"E1","name":"Keep Odoo and UKG labor categories distinct","actor":"Employee","story":"As an employee, I want to see whether a project or labor-category value was prefilled, and change it, so that my time lands in the right place.","trigger":"Employee opens a punch or the weekly calendar","pre":"Values available from Odoo or context","flow":"1. Choose an optional Odoo Project and Task / LOB where offered. 2. Select UKG labor categories separately through the Transfer drawer. 3. Do not assume one source prepopulates the other.","alt":"No Odoo Project value is selected -> the employee may leave it blank in the prototype; production project-requiredness remains open.","rules":"Odoo-to-UKG prefill mapping has not been selected. Source fields, mapping, precedence, overrides, refresh timing, and missing or inactive-value handling remain open.","api":"Odoo assignment data","ev":"Proposed - Odoo-to-UKG mapping remains open","src":"Global Time Entry UI/UX Specification §5.1.1–5.1.5, §9","pri":"Must","cov":"Partial","demo":["ava","punch","","Ava Mitchell > Punch > Odoo project and labor category"],"q":"UI-OPEN-05, Q-12","ac":[["I open project or labor-category fields","I review their source","Odoo Project / Task and UKG labor categories remain separate unless a mapping is approved"]],"specStatus":"Open decision","specRef":"§5.1.1–5.1.5, §9","shots":[{"src":"journeys/prototype/desktop/CC-04-step1.png","alt":"Desktop view: Odoo Project and Task selected in the Punch screen, separate from the labor category fields.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/CC-04-step1.png","alt":"Mobile view: Odoo Project and Task selected in the Punch screen, separate from the labor category fields.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/CC-04-step2.png","alt":"Desktop view: Labor categories staged in the Transfer drawer appear in their own box, separate from the Odoo project and task above.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/CC-04-step2.png","alt":"Mobile view: Labor categories staged in the Transfer drawer appear in their own box, separate from the Odoo project and task above.","caption":"Step 2 · Mobile"}]},{"id":"PU-01","epic":"E1","name":"Punch in with optional Odoo project","actor":"Hourly employee","story":"As an hourly employee, I want to start my shift with the right optional Odoo project and UKG labor categories so that my time is recorded in the right work context.","trigger":"Employee starts work","pre":"Signed in through SSO and punched out. Odoo Project and Task / LOB may be left blank in the prototype; production project-requiredness remains open.","flow":"1. Open Punch while Out. 2. Optionally select an active assigned Odoo Project and Task / LOB. 3. Optionally use Add Transfer, or choose a transfer in the transfer select, to stage UKG labor categories. 4. Tap Punch In. 5. See a brief confirmation with the local time and project details when present.","alt":"No active assigned Odoo projects -> leave Odoo fields blank in the prototype; production behavior depends on the project-requiredness decision. Already punched in -> Punch In is not offered.","rules":"Odoo Project / Task / LOB and UKG Labor Category values are separate. No automatic mapping is implied. Project-requiredness remains open.","api":"POST /v1/timekeeping/timecard (punches.add, action PUNCH_IN, transfer.project)","ev":"Proposed - project-requiredness and integration remain open","src":"Global Time Entry UI/UX Specification §5.1.1–5.1.2, §9","pri":"Must","cov":"Covered","demo":["ava","punch","punch-in","Ava Mitchell > Punch > Punch In"],"q":"Q-06","ac":[["I am punched out and may leave project fields blank","I tap Punch In","I see a confirmation with local time and project details when UKG accepts the punch"]],"specStatus":"Confirmed","specRef":"§5.1.1–5.1.2, §9","shots":[{"src":"journeys/prototype/desktop/PU-01-step1.png","alt":"Desktop view: Punch screen while punched out, showing the optional Odoo Project and Task fields and the Punch In button.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-01-step1.png","alt":"Mobile view: Punch screen while punched out, showing the optional Odoo Project and Task fields and the Punch In button.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-01-step2.png","alt":"Desktop view: Odoo Project picker open, listing only the active projects assigned to the employee.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-01-step2.png","alt":"Mobile view: Odoo Project picker open, listing only the active projects assigned to the employee.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/PU-01-step3.png","alt":"Desktop view: After Punch In with an Odoo project selected, the punch shows as In in Recent punches.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/PU-01-step3.png","alt":"Mobile view: After Punch In with an Odoo project selected, the punch shows as In in Recent punches.","caption":"Step 3 · Mobile"}]},{"id":"PU-12","epic":"E1","name":"Show, hide, or add Odoo projects for Punch","actor":"Hourly employee","story":"As an hourly employee, I want to show, hide, or add the Odoo projects I work on so that the Punch project picker offers the right projects.","trigger":"Employee needs a project that is not in the Punch picker","pre":"Punched out. Odoo project assignments are available in the prototype's simulated catalog.","flow":"1. While Out, open the Project picker and choose Manage Odoo Project. 2. Show or hide assigned projects; hiding changes picker visibility only. 3. Choose Add projects from Odoo to see active projects not yet assigned. 4. Search by project name, client, or event and choose Add. The project becomes assigned, visible, and selected. 5. Choose Done, optionally choose its Task / LOB, and continue with Punch In.","alt":"No matching projects -> explain the empty search result. Hidden projects remain assigned.","rules":"Only active projects are offered. Showing or hiding does not remove an assignment. Odoo projects stay separate from UKG labor categories. Production catalog access, eligibility, assignment, and persistence remain open.","api":"None in the prototype (simulated catalog); production Odoo catalog call remains open","ev":"Proposed - prototype; production catalog access, assignment, and persistence remain open","src":"Global Time Entry UI/UX Specification §5.1.3, §9","pri":"Must","cov":"Covered","demo":["ava","punch","","Ava Mitchell > Punch > Project picker > Manage Odoo Project"],"q":"UI-OPEN-11","ac":[["I am punched out and open the Project picker","I choose Manage Odoo Project, add a project from the catalog, and choose Done","the project is assigned, visible, and selected for my next Punch In"],["I hide an assigned project","I open the Project picker","the project is hidden from the picker but remains assigned"]],"specStatus":"Prototype","specRef":"§5.1.3, §9","shots":[{"src":"journeys/prototype/desktop/PU-12-step1.png","alt":"Desktop view: Odoo Project picker with Manage Odoo Project at the bottom.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-12-step1.png","alt":"Mobile view: Odoo Project picker with Manage Odoo Project at the bottom.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-12-step2.png","alt":"Desktop view: Manage Odoo Project lists the assigned projects with visibility toggles.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-12-step2.png","alt":"Mobile view: Manage Odoo Project lists the assigned projects with visibility toggles.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/PU-12-step3.png","alt":"Desktop view: Add projects from Odoo lists active projects that are not yet assigned, with a search box.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/PU-12-step3.png","alt":"Mobile view: Add projects from Odoo lists active projects that are not yet assigned, with a search box.","caption":"Step 3 · Mobile"},{"src":"journeys/prototype/desktop/PU-12-step4.png","alt":"Desktop view: After Add and Back, the added project is listed as assigned and visible.","caption":"Step 4 · Desktop"},{"src":"journeys/prototype/mobile/PU-12-step4.png","alt":"Mobile view: After Add and Back, the added project is listed as assigned and visible.","caption":"Step 4 · Mobile"}]},{"id":"PU-03","epic":"E1","name":"Start and end a break","actor":"Hourly employee","story":"As an hourly employee, I want to record my meal break so that unpaid break time is excluded and break rules are met.","trigger":"Employee goes on break","pre":"Employee is punched in","flow":"1. Tap Start Break. 2. Status changes to On break; End Break is primary, Punch Out is secondary, and transfers are disabled. No live break timer is shown. 3. Tap End Break. 4. Work resumes on the same project.","alt":"Break shorter than the configured minimum -> a Short break indicator on the affected My Timecard punch cell (TC-01). Country minimums and grace minutes remain open.","rules":"Break start closes the current segment; break end opens a new segment on the same project and task. Paid/unpaid and minimum length are country rules.","api":"POST /v1/timekeeping/timecard (punches.add)","ev":"Confirmed - Spiro documents","src":"Global Time Entry UI/UX Specification §5.1.4, §5.1.10; SRC-02, SRC-03, SRC-04, FSD TK-1","pri":"Must","cov":"Covered","demo":["ava","punch","punch-break","Ava Mitchell > Punch > Start Break"],"q":"Q-04","ac":[["I am punched in on PRJ-4821","I tap Start Break and later End Break","two segments appear on today's timecard row, both on PRJ-4821, and the break is not counted in the daily total"],["my break lasted less than the configured minimum","the timecard is calculated","a Short break exception is shown on that day"]],"specStatus":"Confirmed","specRef":"§5.1.4, §5.1.10","shots":[{"src":"journeys/prototype/desktop/PU-03-step1.png","alt":"Desktop view: Punch screen while punched in, with Start Break available.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-03-step1.png","alt":"Mobile view: Punch screen while punched in, with Start Break available.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-03-step2.png","alt":"Desktop view: On break: End Break is the primary action, Punch Out is secondary, and transfers are disabled.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-03-step2.png","alt":"Mobile view: On break: End Break is the primary action, Punch Out is secondary, and transfers are disabled.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/PU-03-step3.png","alt":"Desktop view: After End Break, the shift is back In and the break is recorded in Recent punches.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/PU-03-step3.png","alt":"Mobile view: After End Break, the shift is back In and the break is recorded in Recent punches.","caption":"Step 3 · Mobile"}]},{"id":"PU-04","epic":"E1","name":"Stage or change UKG labor categories","actor":"Hourly employee","story":"As an hourly employee, I want to stage or change UKG labor-category values so that my shift is charged to the right category.","trigger":"Work context changes","pre":"Employee is punched in; target project is assigned and active","flow":"1. The transfer select shows the current transfer (the home transfer by default); choose a recent transfer, or tap Add Transfer. 2. Choose configured UKG labor-category levels in the Transfer drawer. 3. Review and confirm. 4. While Out, categories are staged for the next Punch In; while In, the transfer applies from that point forward.","alt":"While on break, transfer controls are disabled until the break ends.","rules":"UKG Labor Category Project, Task / LOB, Timecard Code, and Function are separate from Odoo Project and Task / LOB. Required levels and defaults remain open; no Odoo-to-UKG mapping is implied. The Transfer drawer omits Work Rule, Cost Center, and Business Structure.","api":"POST /v1/timekeeping/timecard (punches.add with transfer object)","ev":"Proposed - labor-category profile and mapping remain open","src":"Global Time Entry UI/UX Specification §5.1.5, §9","pri":"Must","cov":"Covered","demo":["ava","punch","punch-transfer","Ava Mitchell > Punch > Transfer"],"q":"Q-12","ac":[["I am Out and choose Add Transfer","I confirm UKG labor categories","they are staged for my next Punch In without implying an Odoo mapping"],["I am In and choose Add Transfer","I confirm UKG labor categories","the transfer applies from that point forward"]],"specStatus":"Prototype","specRef":"§5.1.5, §9","shots":[{"src":"journeys/prototype/desktop/PU-04-step1.png","alt":"Desktop view: Punch screen while punched out, with Add Transfer available to stage labor categories.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-04-step1.png","alt":"Mobile view: Punch screen while punched out, with Add Transfer available to stage labor categories.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-04-step2.png","alt":"Desktop view: Transfer drawer opened from Add Transfer, showing the employee, primary location, and Add Labor Category.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-04-step2.png","alt":"Mobile view: Transfer drawer opened from Add Transfer, showing the employee, primary location, and Add Labor Category.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/PU-04-step3.png","alt":"Desktop view: Labor category step with a Labor Category Project and Task / LOB chosen.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/PU-04-step3.png","alt":"Mobile view: Labor category step with a Labor Category Project and Task / LOB chosen.","caption":"Step 3 · Mobile"},{"src":"journeys/prototype/desktop/PU-04-step4.png","alt":"Desktop view: Transfer review with the chosen labor categories and the Confirm transfer action.","caption":"Step 4 · Desktop"},{"src":"journeys/prototype/mobile/PU-04-step4.png","alt":"Mobile view: Transfer review with the chosen labor categories and the Confirm transfer action.","caption":"Step 4 · Mobile"},{"src":"journeys/prototype/desktop/PU-04-step5.png","alt":"Desktop view: Punch screen after confirming: the labor categories are staged for the next Punch In.","caption":"Step 5 · Desktop"},{"src":"journeys/prototype/mobile/PU-04-step5.png","alt":"Mobile view: Punch screen after confirming: the labor categories are staged for the next Punch In.","caption":"Step 5 · Mobile"}]},{"id":"PU-02","epic":"E1","name":"Punch out to end the shift","actor":"Hourly employee","story":"As an hourly employee, I want to punch out at the end of my shift so that my shift closes with an accurate total.","trigger":"Employee finishes work","pre":"Employee is punched in","flow":"1. Open Punch. 2. Review elapsed shift time. 3. Tap Punch Out. 4. See a brief confirmation with the action and local time.","alt":"On break -> Punch Out also ends the break (break end recorded at the same time).","rules":"Punch Out is only enabled while punched in. Shift total excludes unpaid break time. Prototype: elapsed shift time is not shown on the Punch screen yet.","api":"POST /v1/timekeeping/timecard (punches.add)","ev":"Confirmed - Spiro documents","src":"Global Time Entry UI/UX Specification §5.1.6; SRC-02, SRC-03, SRC-04, SRC-06, FSD TK-1","pri":"Must","cov":"Covered","demo":["ava","punch","punch-out","Ava Mitchell > Punch > Punch Out"],"q":"","ac":[["I am punched in","I tap Punch Out","an OUT punch is recorded and today's row on My Timecard shows the closed segment and daily total"],["I am punched out","I look at the Punch screen","Punch Out is disabled and Punch In is enabled"]],"specStatus":"Confirmed","specRef":"§5.1.6","shots":[{"src":"journeys/prototype/desktop/PU-02-step1.png","alt":"Desktop view: Punch screen while punched in, with Punch Out as the primary action and Start Break as the secondary action.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-02-step1.png","alt":"Mobile view: Punch screen while punched in, with Punch Out as the primary action and Start Break as the secondary action.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-02-step2.png","alt":"Desktop view: After Punch Out, the shift is closed, Punch In is available again, and the Punch Out event is in Recent punches.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-02-step2.png","alt":"Mobile view: After Punch Out, the shift is closed, Punch In is available again, and the Punch Out event is in Recent punches.","caption":"Step 2 · Mobile"}]},{"id":"PU-05","epic":"E1","name":"Blocked punch for unassigned or inactive project","actor":"Hourly employee","story":"As Spiro Finance, I want punches blocked on projects that are closed or not assigned so that time is never charged to the wrong PRJ.","trigger":"Employee selects or scans a project","pre":"Odoo assignment sync has run","flow":"1. The employee selects an Odoo Project from the picker. 2. The picker offers active projects assigned to the employee. 3. Validate the selection again when Punch In is submitted. 4. If it became inactive or unassigned, do not record the punch and show a plain-language message.","alt":"The Odoo Project is optional in the prototype and may be left blank. Whether production punches may start without a project remains open.","rules":"Invalid projects are not offered and are revalidated at submission. Odoo Project validation is separate from UKG labor-category validation. Prototype: the picker offers only active assigned projects, but Punch In does not re-check the selection, so the blocked-project message is not shown.","api":"None (CloudApper validation against Odoo assignment cache)","ev":"Confirmed - picker rule; production requiredness remains open","src":"Global Time Entry UI/UX Specification §5.1.2, §5.1.7, §9","pri":"Must","cov":"Partial","demo":["ava","punch","punch-project","Ava Mitchell > Punch > Project picker"],"q":"Q-06","ac":[["project MUC-1999 is closed in Odoo","I select it in the Project picker and tap Punch In","I see a plain-language message that MUC-1999 is closed and that I must select an active assigned project, and no punch is recorded"]],"specStatus":"Confirmed","specRef":"§5.1.2, §5.1.7, §9","shots":[{"src":"journeys/prototype/desktop/PU-05-step1.png","alt":"Desktop view: Punch screen with the Odoo Project picker available.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-05-step1.png","alt":"Mobile view: Punch screen with the Odoo Project picker available.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-05-step2.png","alt":"Desktop view: Odoo Project picker lists only active projects assigned to the employee; inactive or unassigned projects are not offered.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-05-step2.png","alt":"Mobile view: Odoo Project picker lists only active projects assigned to the employee; inactive or unassigned projects are not offered.","caption":"Step 2 · Mobile"}]},{"id":"PU-07","epic":"E1","name":"See punch confirmation and UKG errors","actor":"Hourly employee","story":"As an hourly employee, I want clear feedback after a punch so that I know whether UKG accepted it.","trigger":"A punch is sent to UKG","pre":"Employee selects a Punch action","flow":"1. CloudApper sends the punch to UKG. 2. If UKG accepts it, show a brief confirmation with the action and local time. 3. Show the recorded event and available project, task, or labor-category details in Recent punches.","alt":"UKG returns an error -> display the error message from UKG, including duplicate-punch errors.","rules":"Show a success confirmation when UKG accepts the punch. If UKG returns an error, show the returned message to the employee.","api":"POST /v1/timekeeping/timecard (punches.add; display the result returned by UKG)","ev":"Confirmed - user clarification","src":"Global Time Entry UI/UX Specification §5.1.8","pri":"Should","cov":"Covered","demo":["ava","punch","recent-punches","Ava Mitchell > Punch > Recent punches"],"q":"","ac":[["I submit a punch","UKG accepts it","I see a brief confirmation with the action and local time"]],"specStatus":"Confirmed","specRef":"§5.1.8","shots":[{"src":"journeys/prototype/desktop/PU-07-step1.png","alt":"Desktop view: Recent punches before a new punch.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-07-step1.png","alt":"Mobile view: Recent punches before a new punch.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-07-step2.png","alt":"Desktop view: After Punch In, the confirmation shows the action and local time, and the event appears in Recent punches.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-07-step2.png","alt":"Mobile view: After Punch In, the confirmation shows the action and local time, and the event appears in Recent punches.","caption":"Step 2 · Mobile"}]},{"id":"PU-08","epic":"E1","name":"Display an error returned by UKG","actor":"Hourly employee","story":"As an hourly employee, I want to see an error returned by UKG when it cannot record my punch so that I know what happened.","trigger":"UKG rejects a punch","pre":"CloudApper has sent a punch to UKG","flow":"1. CloudApper sends the punch to UKG. 2. UKG returns an error. 3. CloudApper displays the error message returned by UKG, including duplicate-punch errors.","alt":"UKG accepts the punch -> show a brief confirmation with the action and local time.","rules":"Display the error returned by UKG to the employee.","api":"POST /v1/timekeeping/timecard (punches.add)","ev":"Confirmed - user clarification","src":"Global Time Entry UI/UX Specification §5.1.8","pri":"Must","cov":"Covered","demo":["ava","punch","sim-punch-error","Punch > simulate a duplicate-punch error from UKG"],"q":"","ac":[["I send a punch to UKG","UKG returns a duplicate-punch error","I see the error message returned by UKG"]],"specStatus":"Confirmed","specRef":"§5.1.8","shots":[{"src":"journeys/prototype/desktop/PU-08-step1.png","alt":"Desktop view: Punch screen before a punch is sent to UKG.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-08-step1.png","alt":"Mobile view: Punch screen before a punch is sent to UKG.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-08-step2.png","alt":"Desktop view: Punch In returns the duplicate-punch error from UKG, and the error is shown as returned; no punch is recorded.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-08-step2.png","alt":"Mobile view: Punch In returns the duplicate-punch error from UKG, and the error is shown as returned; no punch is recorded.","caption":"Step 2 · Mobile"}]},{"id":"PU-11","epic":"E1","name":"Punch-required populations cannot enter flat hours","actor":"Hourly employee","story":"As Spiro HR, I want hourly populations that need wage-and-hour compliance to use real punches so that we hold compliant records.","trigger":"Hourly employee opens time entry","pre":"Population flag set per employee","flow":"1. Employee opens time entry. 2. Punch-required employees see Punch and Timecard (review) but not flat-hours entry.","alt":"Grid-allowed populations (e.g. Poland transition) see the project hours grid.","rules":"Population rule decides which entry views are available.","api":"Employee Master attribute (source to be confirmed)","ev":"Proposed - needs Spiro validation","src":"SRC-07, SRC-03, FSD SEC-2","pri":"Must","cov":"Partial","demo":["ava","timecard","view-switch","Ava (punch) vs Zofia (grid)"],"q":"Q-02","ac":[["I am in a punch-required population","I open My Timecard","flat-hours entry is not offered and I am directed to Punch"]],"specStatus":"Proposed","specRef":"§5.1.9, §9","shots":[{"src":"journeys/prototype/desktop/PU-11-step1.png","alt":"Desktop view: My Timecard for an hourly punch employee: punches and totals only, with no flat-hours entry offered.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-11-step1.png","alt":"Mobile view: My Timecard for an hourly punch employee: punches and totals only, with no flat-hours entry offered.","caption":"Step 1 · Mobile"}]},{"id":"TC-01","epic":"E2","name":"Review my hourly timecard","actor":"Hourly employee","story":"As an hourly employee, I want to review my punches, transfers and hours by day so that I can check my time for the selected period.","trigger":"Employee opens My Timecard","pre":"Signed-in hourly employee; own timecard is available for the selected period. Salaried employees use Project Hours.","flow":"1. Open My Timecard from navigation or Recent punches. 2. Review employee, role, selected period dates and loaded time. 3. Review Date, In, Transfer (Project / Task / LOB), Out, Hours, Daily and Period. 4. Inspect read-only details and project/task totals below the grid.","alt":"Breaks, transfers and split shifts create additional rows. Empty days have blank punch/hour cells and no Absence label; active segments show In progress and missing end punches show a read-only Missed punch label.","rules":"My Timecard is for hourly employees only and is read-only. Edit, Comments, Add punch and correction actions are hidden and disabled. Schedule, Pay Code, Shift, separate Exceptions, Audit, UKG Sync and By Pay Code are omitted. Mobile scrolling stays inside the grid.","api":"POST /v1/timekeeping/employee_timecard/multi_read","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"Must","cov":"Covered","demo":["ava","timecard","timecard-grid","Ava Mitchell > My Timecard"],"q":"Q-01","ac":[["I am an hourly employee viewing a selected period","I open My Timecard","the seven documented columns, header and project/task totals are shown in a read-only view"],["I view My Timecard","I review the grid and details","no edit, comment, add-punch or correction action is offered"]],"specStatus":"Confirmed","specRef":"§5.1.10","shots":[{"src":"journeys/prototype/desktop/TC-01-step1.png","alt":"Desktop view: My Timecard for the current period: daily In, Transfer, Out, Hours, Daily, and Period columns.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TC-01-step1.png","alt":"Mobile view: My Timecard for the current period: daily In, Transfer, Out, Hours, Daily, and Period columns.","caption":"Step 1 · Mobile"}],"currentState":"Read-only. Edit and Comments are hidden and disabled, including in punch and transfer details. Adding, deleting, or correcting a punch and sending a correction request are unavailable; whether employees may edit punches is an open decision (TC-04).","gridFields":[["Date","Show the date on the first row for that day. Keep the column compact on mobile."],["In","Show the segment's recorded start time; open punch details without changing the time."],["Transfer (Project / Task / LOB)","Keep the value on one line and truncate when needed. The details popover shows the full values."],["Out","Show the recorded end time. An active segment shows In progress; a missing end punch shows a read-only Missed punch label."],["Hours","Show the worked hours for the segment, excluding unpaid breaks."],["Daily","Show the day's total on its final row."],["Period","Show the running period total through that day."]]},{"id":"TC-02","epic":"E2","name":"Switch between pay periods","actor":"Hourly employee","story":"As an hourly employee, I want to move between time periods so that I can review my recorded time.","trigger":"Employee uses period navigation","pre":"Current and previous period data are available.","flow":"1. Open My Timecard and read the displayed date range. 2. Select Previous to review the prior period. 3. Use Today or Next to return to the current period.","alt":"At the available period boundary, the corresponding control is disabled. The prototype exposes only the current and previous periods.","rules":"Navigation changes the date range, daily records and totals. Country pay-period rules remain open; all periods remain read-only.","api":"employee_timecard/multi_read with date range","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"Must","cov":"Covered","demo":["ava","timecard","timecard-grid","Ava Mitchell > My Timecard > Previous / Today / Next"],"q":"Q-01","ac":[["I view the current period","I select Previous","the previous period dates, records and totals appear"],["I view the previous period","I select Today or Next","the current period appears and Next is disabled at the current-period boundary"]],"specStatus":"Confirmed","specRef":"§5.1.10","shots":[{"src":"journeys/prototype/desktop/TC-02-step1.png","alt":"Desktop view: My Timecard for the current period, with Previous, Today, and Next controls.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TC-02-step1.png","alt":"Mobile view: My Timecard for the current period, with Previous, Today, and Next controls.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TC-02-step2.png","alt":"Desktop view: Previous period: the dates, recorded punches, and totals change to the prior period.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TC-02-step2.png","alt":"Mobile view: Previous period: the dates, recorded punches, and totals change to the prior period.","caption":"Step 2 · Mobile"}]},{"id":"TC-03","epic":"E2","name":"Open punch and transfer details","actor":"Hourly employee","story":"As an hourly employee, I want to inspect punch times, labor category and transfer information so that I can verify what my timecard records.","trigger":"Employee selects a recorded punch time or transfer","pre":"The selected period contains a recorded In/Out punch or transfer.","flow":"1. Click, tap or right-click a recorded In/Out time or Transfer cell. 2. Review Date, Time and Punch type for a punch, or the full Project/Task allocation and time range for a transfer. 3. Review recorded UKG values in the separate Labor category group. 4. Close the popover, press Escape or click outside.","alt":"When no labor category is recorded, the popover explains this. A truncated Transfer value is shown in full in its details.","rules":"Details remain read-only and have no Edit or Comments actions. Transfer text stays on one line in the grid. Odoo Project/Task values remain separate from UKG labor categories.","api":"POST /v1/timekeeping/employee_timecard/multi_read (simulated detail data)","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"Must","cov":"Covered","demo":["ava","timecard","timecard-grid","Ava Mitchell > My Timecard > select an In/Out time or Transfer"],"q":"Q-03","ac":[["I review a recorded In or Out time","I open its details","Date, Time, Punch and recorded Labor category values appear without Edit or Comments"],["a Transfer value is truncated","I open its details","the full allocation and separate Labor category values are readable"]],"specStatus":"Confirmed","specRef":"§5.1.10","shots":[{"src":"journeys/prototype/desktop/TC-03-step1.png","alt":"Desktop view: My Timecard grid: recorded In and Transfer values open their details.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TC-03-step1.png","alt":"Mobile view: My Timecard grid: recorded In and Transfer values open their details.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TC-03-step2.png","alt":"Desktop view: Punch details for a recorded In time: Date, Time, and Punch type, read-only with no Edit or Comments.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TC-03-step2.png","alt":"Mobile view: Punch details for a recorded In time: Date, Time, and Punch type, read-only with no Edit or Comments.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/TC-03-step3.png","alt":"Desktop view: Transfer details: the full Project / Task allocation and the separate Labor category values.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/TC-03-step3.png","alt":"Mobile view: Transfer details: the full Project / Task allocation and the separate Labor category values.","caption":"Step 3 · Mobile"}]},{"id":"TC-04","epic":"E2","name":"Employee punch editing is an open decision","actor":"Hourly employee","story":"As an hourly employee, I may need to change a recorded In or Out time; whether employee editing will be enabled remains a decision for Spiro.","trigger":"Employee spots an incorrect recorded punch time","pre":"A recorded punch may need a correction; current My Timecard access is read-only.","flow":"1. Review My Timecard and the recorded punch details. 2. The current view provides no Edit or correction-request action. 3. Keep employee punch-edit access open until Spiro confirms Q-05.","alt":"If editing is approved later, define eligible groups, editable periods, reasons, approval handling and direct-save versus Manager-review behavior.","rules":"Punch editing is currently disabled and its controls are hidden. No correction-request route is assumed. Comments, missing-punch addition and employee approval are also unavailable in the current view.","api":"No punch-update call is made from the current read-only view; a future update contract would need confirmation.","ev":"Proposed - employee edit access remains open","src":"Global Time Entry UI/UX Specification §5.1.10; §9, Q-05","pri":"—","cov":"Not prototyped","demo":["ava","timecard","timecard-grid","Ava Mitchell > My Timecard > read-only punch details"],"q":"Q-05","ac":[["I open My Timecard","I review an incorrect or missing punch","no edit or correction-request action is available while Q-05 remains open"]],"specStatus":"Open decision","specRef":"§5.1.10; §9 (Q-05)","shots":[{"src":"journeys/prototype/desktop/TC-04-step1.png","alt":"Desktop view: Punch details are read-only: no Edit, Comments, or correction action is offered while punch editing is an open decision.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TC-04-step1.png","alt":"Mobile view: Punch details are read-only: no Edit, Comments, or correction action is offered while punch editing is an open decision.","caption":"Step 1 · Mobile"}]},{"id":"TC-07","epic":"E2","name":"Review totals by project and task","actor":"Hourly employee","story":"As an hourly employee, I want to review hours by project and task so that I can check how my time is allocated.","trigger":"Employee reaches Totals below the timecard grid","pre":"Punches and transfers are recorded in the selected period.","flow":"1. Review Totals below the timecard grid. 2. Review hours grouped by project and task. 3. Compare the period total with the running totals in the grid.","alt":"No project hours in the period -> the totals table shows its empty state and a zero period total.","rules":"The current view shows project/task totals only. By Pay Code, overtime and premium breakdowns are absent; future additions remain an open decision.","api":"Calculated from the demo timecard segments; production totals source remains to be verified.","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"Must","cov":"Covered","demo":["ava","timecard","totals","Ava Mitchell > My Timecard > Totals"],"q":"Q-08","ac":[["the period contains recorded project hours","I review Totals","the project/task breakdown and period total are shown without a pay-code breakdown"],["the period has no recorded hours","I review Totals","the empty state and zero total appear"]],"specStatus":"Confirmed","specRef":"§5.1.10","shots":[{"src":"journeys/prototype/desktop/TC-07-step1.png","alt":"Desktop view: My Timecard grid above the Totals section.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TC-07-step1.png","alt":"Mobile view: My Timecard grid above the Totals section.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TC-07-step2.png","alt":"Desktop view: Totals grouped by project and task, with the period total.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TC-07-step2.png","alt":"Mobile view: Totals grouped by project and task, with the period total.","caption":"Step 2 · Mobile"}]},{"id":"TC-10","epic":"E2","name":"Audit trail is outside the employee timecard view","actor":"Employee, approver, payroll","story":"Timekeeping audit requirements remain separate from the hourly employee My Timecard review screen.","trigger":"Hourly employee opens My Timecard","pre":"The employee timecard view is available.","flow":"1. Open My Timecard. 2. Review daily records, read-only details and project/task totals. No Audit or UKG Sync tab is available.","alt":"System-level audit retention remains a separate requirement outside this employee screen.","rules":"The current employee view omits Audit and UKG Sync. Separate system audit requirements do not add an employee-screen journey.","api":"No employee audit-screen read is made by this journey.","ev":"Out of scope - current employee view","src":"Global Time Entry UI/UX Specification §5.1.10","pri":"—","cov":"Covered","demo":["ava","timecard","timecard-grid","My Timecard has no Audit or UKG Sync view"],"q":"","ac":[["I open My Timecard","I review the available sections","Audit and UKG Sync tabs are absent"]],"specStatus":"Out of scope","specRef":"§5.1.10","shots":[{"src":"journeys/prototype/desktop/TC-10-step1.png","alt":"Desktop view: My Timecard shows daily records, details, and totals only; there is no Audit or UKG Sync view.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TC-10-step1.png","alt":"Mobile view: My Timecard shows daily records, details, and totals only; there is no Audit or UKG Sync view.","caption":"Step 1 · Mobile"}]},{"id":"GR-01","epic":"E3","name":"Enter hours across projects in a weekly grid","actor":"Salaried employee (and any hourly population approved for grid entry)","story":"As an employee working on several projects, I want to enter hours per project per day in one grid so that I can log my week quickly.","trigger":"Employee records time","pre":"Assigned projects loaded","flow":"1. Open Project hours. 2. Type hours into day cells. 3. Row and column totals update. 4. Choose Save (ghost-style button with a translated name and tooltip). Save records changed rows and shows confirmation.","alt":"Invalid value -> GR-05.","rules":"Hours must be numeric, nonnegative, and have at most two decimal places. Only the current week is editable; adjacent weeks are read-only (§5.2.1).","api":"POST /v1/timekeeping/timecard (paycodeEdits / hours with activity) [SE-verify activity shape]","ev":"Confirmed - Spiro documents","src":"SRC-02, SRC-03, SRC-04, SRC-06, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["zofia","grid","grid","Zofia Kowalska > Project hours"],"q":"UI-OPEN-07","ac":[["I have 3 assigned projects","I type 3 on Monday for PL-8804","the row total and Monday total update immediately"]],"specStatus":"Confirmed","specRef":"§5.2.1–5.2.2","shots":[{"src":"journeys/prototype/desktop/GR-01-step1.png","alt":"Desktop view: Weekly project-hours grid: one row per visible assigned project, seven daily cells, and daily and period totals.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-01-step1.png","alt":"Mobile view: Weekly project-hours grid: one row per visible assigned project, seven daily cells, and daily and period totals.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/GR-01-step2.png","alt":"Desktop view: Hours entered in a day cell update the row and the totals, and the Save button appears.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/GR-01-step2.png","alt":"Mobile view: Hours entered in a day cell update the row and the totals, and the Save button appears.","caption":"Step 2 · Mobile"}]},{"id":"GR-02","epic":"E3","name":"Rows pre-filled from assigned projects","actor":"Employee","story":"As an employee, I want assigned project rows ready in the weekly grid so that I can enter hours without rebuilding the project list.","trigger":"Grid opens for a new week","pre":"Odoo PRJ assignment sync","flow":"1. Open a new week. 2. See a row for each visible assigned project, with seven daily cells and a project total. 3. Use Projects or Manage projects to show or hide assignments; a hidden assignment remains available in Add new > All.","alt":"Large project lists: a Copy & Archive fallback applies only if Q-13 confirms it. The project-count threshold is not yet set (GR-06).","rules":"Odoo Project / Task / LOB and UKG labor-category values remain separate; no mapping is implied. Assignment source and details prefilled onto a row remain open.","api":"Odoo assignment sync (inbound)","ev":"Proposed - project assignment and mapping details remain open","src":"Global Time Entry UI/UX Specification §5.2.1, §9","pri":"Must","cov":"Covered","demo":["zofia","grid","grid","Zofia Kowalska > Project hours"],"q":"UI-OPEN-05","ac":[["I have active assigned projects","I open a new week","visible assigned projects have rows and no Odoo-to-UKG mapping is assumed"]],"specStatus":"Open decision","specRef":"§5.2.1, §9","shots":[{"src":"journeys/prototype/desktop/GR-02-step1.png","alt":"Desktop view: Rows are pre-filled from the employee's assigned, visible projects; hidden projects are not listed.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-02-step1.png","alt":"Mobile view: Rows are pre-filled from the employee's assigned, visible projects; hidden projects are not listed.","caption":"Step 1 · Mobile"}]},{"id":"GR-03","epic":"E3","name":"Add a project row with quick lookup","actor":"Employee","story":"As an employee on many PRJs, I want to search by PRJ number, client or show so that I find the right project fast.","trigger":"Employee needs a project not in the grid","pre":"Project assigned and active","flow":"1. Select Add new. 2. In the drawer, choose the paycode (currently Hours Worked) and search assigned, active projects by number, name, client, or umbrella PRJ. 3. Choose a task when the project requires one, plus any configured Timecard Code or Function. 4. Confirm to add the row. If the project and task already have a row, the employee is directed to that row.","alt":"Project not in list -> contact PM (assignment missing).","rules":"Only assigned, active projects are searchable. Umbrella PRJ shows its child PRJs.","api":"None (CloudApper cache of Odoo assignments)","ev":"Confirmed - Spiro documents","src":"SRC-01, SRC-03, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["zofia","grid","grid-add","Zofia Kowalska > Project hours > Add project"],"q":"Q-13","ac":[["I search 'Warsaw'","results load","only my assigned active projects matching Warsaw are shown"]],"specStatus":"Confirmed","specRef":"§5.2.1","shots":[{"src":"journeys/prototype/desktop/GR-03-step1.png","alt":"Desktop view: Add new opens the transfer drawer on the project step, with the paycode and the transfer box.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-03-step1.png","alt":"Mobile view: Add new opens the transfer drawer on the project step, with the paycode and the transfer box.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/GR-03-step2.png","alt":"Desktop view: Labor category step with PL-8810 chosen and its required task selected.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/GR-03-step2.png","alt":"Mobile view: Labor category step with PL-8810 chosen and its required task selected.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/GR-03-step3.png","alt":"Desktop view: After Apply, the new project row appears in the grid.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/GR-03-step3.png","alt":"Mobile view: After Apply, the new project row appears in the grid.","caption":"Step 3 · Mobile"}]},{"id":"GR-04","epic":"E3","name":"Mandatory fields enforced per PRJ","actor":"Employee","story":"As a PM, I want required fields (such as task) enforced for my PRJ so that time is not charged without the detail we need.","trigger":"Employee saves or submits","pre":"PRJ has mandatory-field rules","flow":"1. Employee leaves Task empty on a PRJ that requires it. 2. Save is blocked and the error appears beside the affected Task value.","alt":"","rules":"Mandatory fields are defined per PRJ.","api":"None (CloudApper validation)","ev":"Confirmed - Spiro documents","src":"SRC-01, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["zofia","grid","grid-add","Zofia > Project hours > Add PL-8810 without a task, enter hours, Submit"],"q":"","ac":[["PL-8810 requires a task","I enter hours without a task and choose Save","saving is blocked and 'PL-8810 needs a task' appears beside the Task value"]],"specStatus":"Confirmed","specRef":"§5.2.1–5.2.2","shots":[{"src":"journeys/prototype/desktop/GR-04-step1.png","alt":"Desktop view: PL-8810 requires a task: the labor category step shows the project with no task chosen.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-04-step1.png","alt":"Mobile view: PL-8810 requires a task: the labor category step shows the project with no task chosen.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/GR-04-step2.png","alt":"Desktop view: Apply is blocked, and the drawer explains that PL-8810 needs a task.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/GR-04-step2.png","alt":"Mobile view: Apply is blocked, and the drawer explains that PL-8810 needs a task.","caption":"Step 2 · Mobile"}]},{"id":"GR-05","epic":"E3","name":"Validate hours entered","actor":"Employee","story":"As payroll, I want impossible values rejected so that bad data never reaches UKG.","trigger":"Employee types a value","pre":"","flow":"1. Type a value. 2. Negative, non-numeric, more than 2 decimals, or a day over 24 hours is flagged at once. 3. Save is blocked until the errors are corrected.","alt":"","rules":"Nonnegative (zero allowed), at most 2 decimals, daily total <= 24. Only the current week is editable; adjacent weeks are read-only (§5.2.1). Comma or dot decimals accepted for EU locales.","api":"None (CloudApper validation)","ev":"Confirmed - Spiro documents","src":"SRC-06, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["zofia","grid","grid","Zofia Kowalska > Project hours > type 30"],"q":"","ac":[["Monday already has 8 hours","I enter 20 on another row for Monday","the cell is flagged 'Day total cannot exceed 24 hours' and save is blocked"]],"specStatus":"Confirmed","specRef":"§5.2.2","shots":[{"src":"journeys/prototype/desktop/GR-05-step1.png","alt":"Desktop view: A day total above 24 hours is flagged at once: 30 hours entered in a single day cell.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-05-step1.png","alt":"Mobile view: A day total above 24 hours is flagged at once: 30 hours entered in a single day cell.","caption":"Step 1 · Mobile"}]},{"id":"GR-06","epic":"E3","name":"Copy last week","actor":"Employee","story":"As an employee on dozens of projects, I want to copy last week's rows so that I only adjust hours.","trigger":"New week","pre":"Previous week has rows","flow":"1. Tap Copy last week. 2. Rows (and optionally hours) copy. 3. Adjust and save.","alt":"Copied project now closed -> row skipped with a note.","rules":"Copy last week is not defined in the current UI/UX specification; its behavior and eligibility remain open. Prototype: no Copy last week control is shown on the grid, so the behavior is not demonstrated.","api":"None","ev":"Proposed - Copy last week is not documented","src":"Journey register Q-13; Global Time Entry UI/UX Specification §5.2.1 does not define Copy last week","pri":"Should","cov":"Not prototyped","demo":["","","","Not prototyped yet"],"q":"Q-13","ac":[["last week had 4 rows, one now closed","I tap Copy last week","3 rows are copied and I see '1 closed project skipped'"]],"specStatus":"Open decision","specRef":"§5.2.1; Q-13"},{"id":"GR-07","epic":"E3","name":"Show or hide assigned projects","actor":"Employee","story":"As an employee, I want to hide assigned projects I do not use so that the weekly grid stays focused.","trigger":"Employee manages the weekly project list","pre":"Assigned projects are available in Project hours","flow":"1. Choose Projects or Manage projects. 2. Hide an assigned project to remove its row from the visible grid. 3. Find the hidden assignment in Add new > All when needed.","alt":"Hiding a project changes visibility only; it does not remove the employee assignment.","rules":"Hidden assigned projects remain available in the Add new > All list.","api":"None","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.2.1","pri":"Could","cov":"Covered","demo":["zofia","grid","grid","Zofia Kowalska > Project hours > Archive"],"q":"Q-13","ac":[["I hide an assigned project","I open Add new > All","the project remains available because hiding did not remove the assignment"]],"specStatus":"Confirmed","specRef":"§5.2.1","shots":[{"src":"journeys/prototype/desktop/GR-07-step1.png","alt":"Desktop view: Projects / Manage projects lists the assigned projects with visibility toggles; hidden projects stay assigned.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-07-step1.png","alt":"Mobile view: Projects / Manage projects lists the assigned projects with visibility toggles; hidden projects stay assigned.","caption":"Step 1 · Mobile"}]},{"id":"GR-08","epic":"E3","name":"Save project hours with the correct employee outcome","actor":"Employee","story":"As an employee, I want to save hours as I enter them so that they are kept with the correct outcome for my employee type.","trigger":"Employee finishes entry","pre":"All rows valid","flow":"1. Enter valid hours. 2. Choose Save. 3. Salaried project hours show Recorded and need no approval (GR-09). Hourly flat-hours entries follow the project-time approval flow, which remains open (§9).","alt":"Validation errors -> submit blocked with the list.","rules":"Drafts are not sent to UKG. Production persistence, UKG integration, and hourly approval routing remain unconfirmed.","api":"POST /v1/timekeeping/timecard on submit","ev":"Confirmed - UI/UX specification for Save and Recorded; hourly approval routing remains open","src":"Global Time Entry UI/UX Specification §5.2.2, §9","pri":"Must","cov":"Covered","demo":["zofia","grid","grid-submit","Zofia Kowalska > Project hours > Submit"],"q":"Q-09","ac":[["all rows are valid","I choose Save","salaried rows show Recorded; hourly rows enter the project-time approval flow once its routing is confirmed"]],"specStatus":"Open decision","specRef":"§5.2.2, §9","shots":[{"src":"journeys/prototype/desktop/GR-08-step1.png","alt":"Desktop view: Valid hours entered; Save is now available.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-08-step1.png","alt":"Mobile view: Valid hours entered; Save is now available.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/GR-08-step2.png","alt":"Desktop view: After Save, the hours are saved and the row shows the outcome for the employee's type.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/GR-08-step2.png","alt":"Mobile view: After Save, the hours are saved and the row shows the outcome for the employee's type.","caption":"Step 2 · Mobile"}]},{"id":"GR-09","epic":"E3","name":"Salaried project time without approval","actor":"Salaried employee","story":"As a salaried employee, I want to record project and task time without punches or an approval step so that it takes me minutes a week.","trigger":"Weekly entry","pre":"Salaried flag; assigned projects","flow":"1. Open Project hours. 2. Enter hours by project and task. 3. Choose Save. 4. Rows show Recorded; no approval step applies.","alt":"","rules":"Per the Business Requirements, salaried project hours do not require approval.","api":"POST /v1/timekeeping/timecard (activity hours) [SE-verify]","ev":"Confirmed - Spiro documents","src":"SRC-01, SRC-04, FSD TK-2, TK-3","pri":"Must","cov":"Covered","demo":["maya","grid","grid-submit","Maya Chen > Project hours > Submit"],"q":"UI-OPEN-07","ac":[["I am salaried","I choose Save for my week","rows show Recorded and none appear in an approval queue"]],"specStatus":"Confirmed","specRef":"§5.2","shots":[{"src":"journeys/prototype/desktop/GR-09-step1.png","alt":"Desktop view: Salaried employee enters project hours; Save becomes available once a value changes.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-09-step1.png","alt":"Mobile view: Salaried employee enters project hours; Save becomes available once a value changes.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/GR-09-step2.png","alt":"Desktop view: After Save, the salaried rows show Recorded and no approval step applies.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/GR-09-step2.png","alt":"Mobile view: After Save, the salaried rows show Recorded and no approval step applies.","caption":"Step 2 · Mobile"}]},{"id":"GR-10","epic":"E3","name":"Correct a returned hourly line and save again","actor":"Employee","story":"As an hourly flat-hours employee, I want to see the approver note and correct a returned line so that I can save the revised hours.","trigger":"Approver rejects a line","pre":"A project-time row is returned with an approver note.","flow":"1. Open Project hours. 2. Review the returned row, approver note, and page-level notice. 3. Correct the hours. 4. Save; the row returns to the pending approval flow.","alt":"","rules":"The prototype stores a line sent back for correction as Rejected with the approver's note; the status name for a returned line remains open. Project-time approver roles, routing, and review steps remain open.","api":"Notification + timecard update","ev":"Proposed - project-time approval remains open","src":"Global Time Entry UI/UX Specification §5.2.2, §9","pri":"Must","cov":"Covered","demo":["zofia","grid","grid","Reject as Oliver, then open Zofia > Project hours"],"q":"UI-OPEN-06","ac":[["an hourly project-time row is returned with a note","I correct the hours and save","the row returns to the pending review flow"]],"specStatus":"Open decision","specRef":"§5.2.2, §9","shots":[{"src":"journeys/prototype/desktop/GR-10-step1.png","alt":"Desktop view: The approver opens a pending hourly line and enters a required note before Reject can be used.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-10-step1.png","alt":"Mobile view: The approver opens a pending hourly line and enters a required note before Reject can be used.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/GR-10-step2.png","alt":"Desktop view: After Reject, the employee's grid shows the line as Rejected with the approver's note.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/GR-10-step2.png","alt":"Mobile view: After Reject, the employee's grid shows the line as Rejected with the approver's note.","caption":"Step 2 · Mobile"}]},{"id":"GR-11","epic":"E3","name":"Reminder to enter time","actor":"Employee","story":"As Resource Management, I want employees reminded to enter time so that data is complete for reporting.","trigger":"Scheduled check finds missing time","pre":"Reminder schedule configured","flow":"1. The current-week reminder flags empty earlier weekdays and shows the Friday 17:00 deadline. 2. Its link opens the current week to complete. Email delivery is not in the spec; confirm the channel (Q-14).","alt":"","rules":"The prototype reminder says time is due Friday at 17:00. Confirm the production reminder rule and due time before release.","api":"CloudApper notification service","ev":"Proposed - production reminder schedule remains open","src":"Global Time Entry UI/UX Specification §5.2.1, Q-14","pri":"Should","cov":"Partial","demo":["zofia","grid","reminder","Zofia Kowalska > banner"],"q":"Q-14","ac":[["I have empty earlier weekdays in the current week","I open Project hours","the reminder flags those weekdays, shows the Friday 17:00 deadline, and links to the open week"]],"specStatus":"Open decision","specRef":"§5.2.1; Q-14","shots":[{"src":"journeys/prototype/desktop/GR-11-step1.png","alt":"Desktop view: Current-week reminder: empty earlier weekdays are flagged, with the Friday 17:00 deadline.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/GR-11-step1.png","alt":"Mobile view: Current-week reminder: empty earlier weekdays are flagged, with the Friday 17:00 deadline.","caption":"Step 1 · Mobile"}]},{"id":"TO-01","epic":"E4","name":"Review the current balance before submitting","actor":"Employee","story":"As an employee, I want to see the selected request type balance on final review so that I can consider it before submitting.","trigger":"Employee opens Time Off","pre":"Balances synced from UKG","flow":"1. Choose a request type, dates, and duration. 2. On final review, see the current balance for that type with its unit and as-of time. 3. Do not show a projected balance or repeat it on confirmation.","alt":"Current balance cannot be retrieved -> label it unavailable; never present an older balance as current.","rules":"Show a balance only on the final review step before submission.","api":"UKG accrual balances","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.3.1–5.3.3","pri":"Must","cov":"Covered","demo":["ava","timeoff","","Ava Mitchell > Time Off > New request > final review"],"q":"UI-OPEN-08","ac":[["I review a Time Off request before submission","I reach final review","I see the current selected-type balance with unit and as-of time, not a projected balance"]],"specStatus":"Confirmed","specRef":"§5.3.1–5.3.3","shots":[{"src":"journeys/prototype/desktop/TO-01-step1.png","alt":"Desktop view: New request: the type and dates are chosen on the request form.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TO-01-step1.png","alt":"Mobile view: New request: the type and dates are chosen on the request form.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TO-01-step2.png","alt":"Desktop view: Final review: the request summary with the current balance and its as-of time before submitting.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TO-01-step2.png","alt":"Mobile view: Final review: the request summary with the current balance and its as-of time before submitting.","caption":"Step 2 · Mobile"}]},{"id":"TO-02","epic":"E4","name":"Request Time Off","actor":"Employee","story":"As an employee, I want to request configured Time Off dates and duration so that the request can follow its documented status flow.","trigger":"Employee needs time off","pre":"Leave types configured","flow":"1. Choose an eligible request type. 2. Choose dates and a configured duration. Full Day uses an inclusive date range; Hours and both half-day durations use one date. 3. Add an optional note and review the request, including the current balance. 4. Submit once. 5. Show the request reference, dates, duration, and returned status: Submitted or a confirmed final status.","alt":"Submission or status is uncertain -> preserve entered data and explain the next step without showing a false success.","rules":"Show only configured eligible request types and durations. Do not repeat balance on confirmation. The policy matrix and eligibility remain open.","api":"Time Off request (UKG pattern)","ev":"Confirmed - UI/UX specification; eligibility policy open","src":"Global Time Entry UI/UX Specification §5.3.2–5.3.4, §9","pri":"Must","cov":"Covered","demo":["ava","timeoff","","Ava Mitchell > Time Off > New request > submit"],"q":"UI-OPEN-08","ac":[["I choose an eligible type, date, and duration","I submit once","I see the request reference, dates, duration, and Submitted or a confirmed final status"]],"specStatus":"Open decision","specRef":"§5.3.2–5.3.4, §9","shots":[{"src":"journeys/prototype/desktop/TO-02-step1.png","alt":"Desktop view: Request form with the type, dates, and optional note entered.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TO-02-step1.png","alt":"Mobile view: Request form with the type, dates, and optional note entered.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TO-02-step2.png","alt":"Desktop view: Review before submitting: the request is sent once, and the button is disabled while it is sent.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TO-02-step2.png","alt":"Mobile view: Review before submitting: the request is sent once, and the button is disabled while it is sent.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/TO-02-step3.png","alt":"Desktop view: Confirmation shows the request reference, returned status, dates, and duration, without the balance.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/TO-02-step3.png","alt":"Mobile view: Confirmation shows the request reference, returned status, dates, and duration, without the balance.","caption":"Step 3 · Mobile"}]},{"id":"TO-03","epic":"E4","name":"Date rules by leave type and region","actor":"Employee","story":"As an employee, I want clear date rules so that I do not submit a request that will be refused.","trigger":"Employee picks dates","pre":"Regional leave-date rules configured","flow":"1. Choose a request type. 2. Select valid dates and a configured duration. 3. Allow past dates only for Sick Time; all other request types accept today or future dates.","alt":"Undefined regional rule -> the affected check is blocked with a message.","rules":"Full Day accepts an inclusive range. Hours, First Half Day, and Second Half Day each use one date. Any Sick Time lookback limit remains to be configured.","api":"None (CloudApper validation)","ev":"Confirmed - UI/UX specification; remaining policy rules open","src":"Global Time Entry UI/UX Specification §5.3.2–5.3.4, §9","pri":"Should","cov":"Covered","demo":["ava","timeoff","","Ava Mitchell > Time Off > Sick Time and PTO dates"],"q":"UI-OPEN-08","ac":[["I choose sick time","I pick yesterday","the date is accepted"],["I choose PTO","I pick yesterday","I see that PTO needs today or a future date"]],"specStatus":"Confirmed","specRef":"§5.3.2–5.3.4","shots":[{"src":"journeys/prototype/desktop/TO-03-step1.png","alt":"Desktop view: Sick Time: past dates are allowed for this type.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TO-03-step1.png","alt":"Mobile view: Sick Time: past dates are allowed for this type.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TO-03-step2.png","alt":"Desktop view: PTO: only today or a future date is accepted for this type.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TO-03-step2.png","alt":"Mobile view: PTO: only today or a future date is accepted for this type.","caption":"Step 2 · Mobile"}]},{"id":"TO-04","epic":"E4","name":"Track my request status","actor":"Employee","story":"As an employee, I want to see my request status so that I know whether it was approved.","trigger":"Request submitted","pre":"Request exists","flow":"1. Open My requests. 2. See Approved, Refused, Submitted, or Cancelled, who needs to act next when known, and chronological status history or comments.","alt":"Latest status cannot be confirmed -> keep the last confirmed status visible and show an update message with its last-updated time and offer Try again.","rules":"Use the actual UKG Time Off request statuses as the request-status values: Approved, Refused, Submitted, and Cancelled. Do not substitute inferred statuses. Translate displayed labels into the selected language while preserving this status mapping.","api":"UKG status sync","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.3.2–5.3.4","pri":"Must","cov":"Covered","demo":["ava","timeoff","","Ava Mitchell > Time Off > My requests"],"q":"UI-OPEN-08","ac":[["A request is awaiting action","I open My requests","I see Submitted and who needs to act next when known"],["my manager refused a request with a reason","I open My requests","I see Refused and the manager reason in request history"]],"specStatus":"Confirmed","specRef":"§5.3.2–5.3.4","shots":[{"src":"journeys/prototype/desktop/TO-04-step1.png","alt":"Desktop view: My requests lists the employee's requests with their status: Submitted, Approved, Refused, or Cancelled.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TO-04-step1.png","alt":"Mobile view: My requests lists the employee's requests with their status: Submitted, Approved, Refused, or Cancelled.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TO-04-step2.png","alt":"Desktop view: A request's details show its status, dates, and history.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TO-04-step2.png","alt":"Mobile view: A request's details show its status, dates, and history.","caption":"Step 2 · Mobile"}]},{"id":"TO-05","epic":"E4","name":"Approve or refuse a managed employee request","actor":"Line Manager / Project Owner","story":"As a Manager, I want to review requests for employees I manage so that I can make a clear Time Off decision.","trigger":"Request reaches my queue","pre":"A Submitted request is in the Manager queue for an employee they manage.","flow":"1. Open Requests needing review in the CloudApper custom app and filter by status, employee, type, or date. 2. Review the employee, request, dates, units, note, deadline when applicable, and relevant history. 3. Confirm Approve or Refuse. 4. Enter a required reason before Refuse. 5. Save the decision and notify the employee with its result and timestamp.","alt":"No assigned Manager -> exception handling is still open; do not introduce a new request status.","rules":"Managers review only employees they manage. Only Submitted requests can be approved or refused. Refusal requires a reason saved to history and shared with the employee.","api":"Time Off status sent to UKG","ev":"Confirmed - UI/UX specification; no-Manager exception open","src":"Global Time Entry UI/UX Specification §5.3.5–5.3.6, §9","pri":"Must","cov":"Covered","demo":["oliver","timeoff","","Oliver Grant > Time Off > Team requests"],"q":"UI-OPEN-04","ac":[["I refuse a Submitted request without a reason","I try to confirm the decision","Refuse remains unavailable until I enter a reason"],["I enter a reason and confirm Refuse","the decision is saved","the employee sees Refused with the reason"]],"specStatus":"Confirmed","specRef":"§5.3.5–5.3.6","shots":[{"src":"journeys/prototype/desktop/TO-05-step1.png","alt":"Desktop view: Requests needing review: the Manager's team queue lists Submitted requests for the employees they manage.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TO-05-step1.png","alt":"Mobile view: Requests needing review: the Manager's team queue lists Submitted requests for the employees they manage.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TO-05-step2.png","alt":"Desktop view: Refuse needs a reason: the reason is entered before the decision can be confirmed.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TO-05-step2.png","alt":"Mobile view: Refuse needs a reason: the reason is entered before the decision can be confirmed.","caption":"Step 2 · Mobile"}]},{"id":"TO-06","epic":"E4","name":"Automatically approve an eligible request after three days","actor":"System","story":"As Spiro HR, I want an eligible request with no Manager decision after three days to become Approved so that the configured rule can complete it.","trigger":"Three days pass after submission without a Manager decision","pre":"The request remains Submitted and matches the configured eligibility rule.","flow":"1. Check the request against configured eligibility. 2. If it remains Submitted without a Manager decision for three days, set status to Approved. 3. Record the automatic decision, rule, and timestamp in history. 4. Notify the employee and remove it from the Manager review queue.","alt":"Eligibility criteria, how the three days are counted, and exception routing remain open.","rules":"Automatic approval is a CloudApper configuration rule. Keep the actual status Approved; do not create an Auto-approved status.","api":"Configuration","ev":"Confirmed - three-day rule; eligibility and timing details remain open","src":"Global Time Entry UI/UX Specification §5.3.3–5.3.6, §9","pri":"Should","cov":"Covered","demo":["ava","timeoff","","Ava Mitchell > Time Off > PTO automatic approval"],"q":"UI-OPEN-04, UI-OPEN-08","ac":[["a configured eligible request remains Submitted without a Manager decision for three days","the rule runs","the request becomes Approved and history records the rule and decision time"]],"specStatus":"Open decision","specRef":"§5.3.3–5.3.6, §9","shots":[{"src":"journeys/prototype/desktop/TO-06-step1.png","alt":"Desktop view: A PTO request still Submitted shows its automatic-approval deadline.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TO-06-step1.png","alt":"Mobile view: A PTO request still Submitted shows its automatic-approval deadline.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TO-06-step2.png","alt":"Desktop view: After the three-day rule runs, the history records the automatic decision, the rule, and the time.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TO-06-step2.png","alt":"Mobile view: After the three-day rule runs, the history records the automatic decision, the rule, and the time.","caption":"Step 2 · Mobile"}]},{"id":"TO-07","epic":"E4","name":"Cancel a request only while it is Submitted","actor":"Employee","story":"As an employee, I want to cancel my own Submitted request so that I can change plans.","trigger":"Plans change","pre":"The request belongs to the employee and its current status is Submitted.","flow":"1. Open the request. 2. Choose Cancel. 3. After CloudApper confirms, show Cancelled and keep the request in history.","alt":"Approved, Refused, or Cancelled request -> no employee cancel action is offered.","rules":"Employees cannot edit a submitted request. Cancellation is available only for the employee's own Submitted request.","api":"Time Off status sync","ev":"Confirmed - UI/UX specification","src":"Global Time Entry UI/UX Specification §5.3.2–5.3.4","pri":"Could","cov":"Covered","demo":["ava","timeoff","","Ava Mitchell > Time Off > Cancel a Submitted request"],"q":"UI-OPEN-08","ac":[["my request is Submitted","I cancel it","after confirmation it shows Cancelled and remains in history"]],"specStatus":"Confirmed","specRef":"§5.3.2–5.3.4","shots":[{"src":"journeys/prototype/desktop/TO-07-step1.png","alt":"Desktop view: A Submitted request offers Cancel; the employee cannot edit it.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/TO-07-step1.png","alt":"Mobile view: A Submitted request offers Cancel; the employee cannot edit it.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/TO-07-step2.png","alt":"Desktop view: After confirming, the request shows Cancelled and stays in history.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/TO-07-step2.png","alt":"Mobile view: After confirming, the request shows Cancelled and stays in history.","caption":"Step 2 · Mobile"}]},{"id":"PU-09","epic":"E5","name":"Identify at a shared kiosk","actor":"Warehouse employee (Germany and Poland)","story":"As a warehouse employee without a company phone, I want to identify myself at a shared device so that I can punch without using my personal phone.","trigger":"Employee arrives at the shared device","pre":"Shared kiosk station available (shared-account provisioning remains open, §9); the employee's badge can be matched to a UKG person (production lookup remains open)","flow":"1. On the kiosk home, select Punch In, Punch Out, or Recent Punches. 2. Scan your badge; authentication is badge-only, with no employee number, username, or password. 3. After acceptance, the selected action is recorded, or your recent punches are shown. No employee details appear before acceptance. 4. The kiosk returns home after the result toast, Back or Cancel, or the 60-second countdown.","alt":"Badge not recognised or invalid -> a clear error; nothing is recorded and the kiosk returns home. Barcode values are not shown in errors.","rules":"Each action requires its own badge scan. Scan and history countdowns are 60 seconds. After returning home, no badge, employee identity, action, history, or detailed result stays visible apart from the brief result toast. Badge encoding, lookup, and authorization remain open (§9). The main prototype's kiosk still has the earlier job-barcode step until the kiosk branch is merged; the screenshots follow the spec.","api":"Badge -> person lookup (source to be confirmed)","ev":"Confirmed - user-approved kiosk flow (§5.5.1–5.5.4); production badge lookup and authorization remain open","src":"Global Time Entry UI/UX Specification §5.5.1–5.5.4","pri":"Should","cov":"Prototype differs","demo":["lukas","kiosk","kiosk-badge","Lukas Weber > Kiosk > Scan badge"],"q":"UI-OPEN-01","ac":[["I am at the shared kiosk","I select Punch In and scan my badge","after acceptance I see a brief result toast with the action and local time, and the kiosk returns home"],["I select Recent Punches and scan my badge","I wait 60 seconds or tap Back","my history clears and the kiosk returns to its three-tile home screen"]],"specStatus":"Confirmed","specRef":"§5.5.1–5.5.4","shots":[{"src":"journeys/prototype/desktop/PU-09-step1.png","alt":"Desktop view: Kiosk home with three equal tiles, Punch In, Punch Out, and Recent Punches; no employee details are shown.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-09-step1.png","alt":"Mobile view: Kiosk home with three equal tiles, Punch In, Punch Out, and Recent Punches; no employee details are shown.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/PU-09-step2.png","alt":"Desktop view: After Punch In is selected, the kiosk asks for the badge scan only.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/PU-09-step2.png","alt":"Mobile view: After Punch In is selected, the kiosk asks for the badge scan only.","caption":"Step 2 · Mobile"},{"src":"journeys/prototype/desktop/PU-09-step3.png","alt":"Desktop view: After the badge is accepted, a brief result appears and the kiosk returns home.","caption":"Step 3 · Desktop"},{"src":"journeys/prototype/mobile/PU-09-step3.png","alt":"Mobile view: After the badge is accepted, a brief result appears and the kiosk returns home.","caption":"Step 3 · Mobile"}]},{"id":"PU-10","epic":"E5","name":"Scan a job barcode to switch project (out of scope)","actor":"Warehouse employee (Germany and Poland)","story":"As a warehouse employee, I might want to scan a job barcode to change project. The spec requests no job or project barcode at the kiosk, so this journey is recorded only to show that decision.","trigger":"Employee moves to a different job","pre":"Not applicable: the kiosk requests no job or project barcode (§3.1, §5.5.2).","flow":"Not in scope. Kiosk actions are Punch In, Punch Out, and Recent Punches after a badge scan (§5.5.1–5.5.2). No project or labor-category selection is included at the kiosk.","alt":"None.","rules":"Spec §3.1 and §5.5 request no job or project barcode. The prototype still shows a job-barcode step, which must be removed before release. The main prototype's kiosk still has the earlier job-barcode step until the kiosk branch is merged; the screenshots follow the spec.","api":"None in kiosk scope.","ev":"Out of scope - the prototype still shows a job-barcode step","src":"Global Time Entry UI/UX Specification §3.1, §5.5.2","pri":"—","cov":"Prototype differs","demo":["lukas","kiosk","kiosk-scan","Lukas Weber > Kiosk > scan BER-1102"],"q":"","ac":[["I am a kiosk user","I select Punch In","the kiosk asks me to scan my badge, not a job barcode"]],"specStatus":"Out of scope","specRef":"§3.1, §5.5.1–5.5.2","shots":[{"src":"journeys/prototype/desktop/PU-10-step1.png","alt":"Desktop view: Punch In at the kiosk asks for the badge only; no job or project barcode is requested.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/PU-10-step1.png","alt":"Mobile view: Punch In at the kiosk asks for the badge only; no job or project barcode is requested.","caption":"Step 1 · Mobile"}]},{"id":"KI-01","epic":"E5","name":"Recent punches at the kiosk","actor":"Warehouse employee (Germany and Poland)","story":"As a warehouse employee at a shared kiosk, I want to see my recent punches so that I can check what was recorded.","trigger":"Employee checks recent punches at the kiosk","pre":"Kiosk station available. The badge can be matched to a UKG person (production lookup remains open).","flow":"1. On the kiosk home, select Recent Punches. 2. Scan your badge; authentication is badge-only. 3. The history shows up to six latest events, newest first, with the label, local time and date, and project detail when applicable. 4. Back, or the 60-second countdown, returns home and clears the history.","alt":"Badge not recognised or invalid -> a clear error with no history, and the kiosk returns home. No events -> an empty-state message.","rules":"Up to six events, newest first. No employee name, badge verified banner, or footer. The history clears on return home. The main prototype's kiosk still has the earlier job-barcode step until the kiosk branch is merged; the screenshots follow the spec.","api":"Badge -> person lookup (source to be confirmed); punch history read (to be confirmed)","ev":"Confirmed - user-approved kiosk flow (§5.5.3); production lookup remains open","src":"Global Time Entry UI/UX Specification §5.5.3","pri":"Should","cov":"Prototype differs","q":"UI-OPEN-01","demo":["lukas","kiosk","","Lukas Weber > Kiosk > Recent Punches"],"ac":[["I select Recent Punches on the kiosk","I scan my badge","I see up to six events, newest first, with no employee name"],["I select Recent Punches on the kiosk","I wait 60 seconds or tap Back","the history clears and the kiosk returns home"]],"specStatus":"Confirmed","specRef":"§5.5.3","shots":[{"src":"journeys/prototype/desktop/KI-01-step1.png","alt":"Desktop view: Recent Punches opens the badge scan screen with a 60-second countdown.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/KI-01-step1.png","alt":"Mobile view: Recent Punches opens the badge scan screen with a 60-second countdown.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/KI-01-step2.png","alt":"Desktop view: After the badge is accepted, up to six recent events are shown, newest first, with no employee name.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/KI-01-step2.png","alt":"Mobile view: After the badge is accepted, up to six recent events are shown, newest first, with no employee name.","caption":"Step 2 · Mobile"}]},{"id":"KI-02","epic":"E5","name":"Kiosk timeout, cancel, and return home","actor":"Warehouse employee (Germany and Poland)","story":"As a warehouse employee at a shared kiosk, I want the kiosk to clear my information after a timeout so that the next person does not see my details.","trigger":"Employee leaves the kiosk or the scan is not completed","pre":"A scan or history screen is open on the kiosk.","flow":"1. The scan screen shows a 60-second countdown. 2. Back or Cancel clears the action and returns home at once. 3. If the countdown ends, the action is cleared, the kiosk explains the timeout, and it returns home. 4. The history clears after its 60-second countdown and returns home without a message.","alt":"After a recorded punch, the brief result toast appears and the kiosk returns home.","rules":"Leave no badge, employee identity, action, history, or detailed result visible after returning home, apart from the brief result toast. Outage handling and the production timeout remain open (§5.5.2). The main prototype's kiosk still has the earlier job-barcode step until the kiosk branch is merged; the screenshots follow the spec.","api":"None (kiosk session state only)","ev":"Confirmed - user-approved kiosk flow (§5.5.4); outage handling remains open","src":"Global Time Entry UI/UX Specification §5.5.4","pri":"Should","cov":"Prototype differs","q":"UI-OPEN-01","demo":["lukas","kiosk","","Lukas Weber > Kiosk > Scan countdown"],"ac":[["I start Punch In on the kiosk","I wait 60 seconds without scanning","the action is cleared, the timeout is explained, and the kiosk returns home"],["I start Punch In on the kiosk","I tap Back or Cancel on the scan screen","the action clears at once and the kiosk returns home"]],"specStatus":"Confirmed","specRef":"§5.5.4","shots":[{"src":"journeys/prototype/desktop/KI-02-step1.png","alt":"Desktop view: The scan screen shows its 60-second countdown; Back or Cancel clears the action at once.","caption":"Step 1 · Desktop"},{"src":"journeys/prototype/mobile/KI-02-step1.png","alt":"Mobile view: The scan screen shows its 60-second countdown; Back or Cancel clears the action at once.","caption":"Step 1 · Mobile"},{"src":"journeys/prototype/desktop/KI-02-step2.png","alt":"Desktop view: After Back, the kiosk returns to its home screen with no badge or action left visible.","caption":"Step 2 · Desktop"},{"src":"journeys/prototype/mobile/KI-02-step2.png","alt":"Mobile view: After Back, the kiosk returns to its home screen with no badge or action left visible.","caption":"Step 2 · Mobile"}]}];
